"""One picture of food that tastes of one ingredient.

A single perfect ripe strawberry, macro-photographed, glossy with dew,
filling the frame against a dark background. This entry writes that
picture to the output directory on every run.
"""

import base64
import os

# The picture lives inside this file as base64, so no binary file is needed.
# Rebuilt fresh for this competition window: one strawberry, one ingredient.
IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
